/* tyre-set price by rim size (₹, set of 4) – rough Chennai market */
const TYRE_COST={12:7000,13:8000,14:10000,15:13000,16:19000,17:26000,18:34000,19:42000,20:50000};



/* Fuel-specific service extras over the petrol-manual 5-yr total (₹). Default diesel +4,000, CNG +3,000. */
const SVCX={punch:{CNG:12000},xuv3xo:{CNG:12000},dzire:{CNG:1700},swift:{CNG:3000},sonet:{D:2575},venue:{D:6000},creta:{D:2900}};
/* Gearbox upkeep allowance, 5 yrs at ~10k km/yr (₹). EXPECTED value = chance of repair × typical repair cost, from owner reports – estimates. */
const GBX={MT:0,iMT:6000,AMT:7500,AT:9000,DCA:12000,DCT:10000};
const GBX_OV={'punch|AMT':10000,'nexon|AMT':10000,'xuv3xo|AMT':10000,'venue|DCT':8000,'tiago|AMT':10000,'tigor|AMT':10000,'altroz|AMT':10000,'virtus|DCT':14000,'taigun|DCT':14000,'slavia|DCT':14000,'kushaq|DCT':14000,'kiger|AT':10000,'magnite|AT':10000,'city|AT':9000,'seltos|DCT':8000,'syros|DCT':8000,'clavis|DCT':8000,'i20|DCT':8000,'verna|DCT':8000};
const GBX_HY=4000;
/* Gearbox notes shown on the variant detail and comparator */
const GBX_NOTE={
 'maruti-amt':'Maruti AGS/AMT (single-clutch automated manual): owners report clutch judder and slow shifts, mostly on older Celerio/Alto/Dzire AGS; clutch jobs quoted ₹3–7k (2016–17, Team-BHP). Described as improving. Allowance ₹7,500.',
 'maruti-tc':'6-speed torque-converter automatic: smooth and durable; budget an ATF change (₹5k at an independent garage to ₹25k at a Hyundai dealer for a Creta AT – Team-BHP). Allowance ₹9,000.',
 'hybrid':'Strong-hybrid e-CVT: no clutch; no fluid-change schedule or hybrid-battery warranty cost found – verify with Maruti. Allowance ₹4,000.',
 'tata-amt':'Tata AMT: Team-BHP rates the Punch AMT ≈6/10 and “extremely jerky in heavy traffic”; Tata/Mahindra AMTs called poorly tuned on small engines; a Tiago AMT actuator replacement was reported but no price found. Allowance ₹10,000.',
 'tata-dca':'Tata DCA (7-speed dual clutch): owners and Autocar flag judder/hesitation in slow traffic on automatics; no repair prices found. Allowance ₹12,000.',
 'hyundai-dct':'Hyundai/Kia 7-speed DCT: Team-BHP calls the Venue DCT “trouble-free so far”; Seltos/Creta DCT owners reported judder, clutch quoted ₹70–90k at ≈65k km (city life ≈50–70k km). Covered by Hyundai 3-yr unlimited-km / Kia 3-yr warranty. Allowance ₹8–10k.',
 'imt':'Kia iMT (clutchless manual): one Sonet owner paid ≈₹28k for a clutch at 46k km and ≈₹80k for a clutch actuator at 52k km (the second covered by extended warranty). Allowance ₹6,000.',
 'mahindra-amt':'Mahindra diesel automatic is an AMT; Mahindra AMTs have a poor record (TUV300 discontinued). No 3XO-specific fault reports found. Allowance ₹10,000.',
 'kylaq-at':'Kylaq AT is a 6-speed torque converter, not the DQ200 DSG that draws reliability concerns on Slavia/Kushaq 1.5 TSI. No Kylaq gearbox faults found. Allowance ₹9,000 (ATF change).',
 'hyundai-amt':'Hyundai/Kia 5-speed AMT (Exter, Aura, Grand i10 Nios): single-clutch automated manual; owners report low-speed jerk but no widespread failures; clutch life is the main wear item. Allowance ₹7,500 (estimate).',
 'renault-amt':'Renault/Nissan 5-speed AMT: owners report slow shifts and creep; clutch service is the main cost. No repair prices found. Allowance ₹7,500 (estimate).',
 'cvt':'CVT (Honda; also Renault/Nissan X-Tronic in the Kiger/Magnite turbo): smooth, but needs fluid changes on schedule; Honda CVT is reputed durable. Allowance ₹9,000–10,000 (estimate).',
 'hyundai-ivt':'Hyundai iVT (CVT on the 1.5 NA petrol): smooth with few reported faults; follow the fluid-change interval. Allowance ₹9,000 (estimate).',
 'dsg':'VW/Skoda 7-speed DSG (1.5 TSI): sporty, but dry-clutch DSGs have drawn owner reports of judder and mechatronic issues; some parts are costly; warranty 4 yr/1 lakh km. Allowance ₹14,000 (estimate).',
 'ev':'Electric: single-speed reduction gear, no clutch or gearbox fluid changes; battery and motor carry an 8-yr warranty on most models (check the car’s own terms). No gearbox allowance.',
 'tc-other':'6-speed torque-converter automatic: smooth and durable; budget an ATF change (₹5k–25k quoted). Allowance ₹9,000.'};

