 punch:[
  ['Service','Spinny 5-yr schedule ₹22.8–24.5k (≈₹4.2–6k a visit at 15,000 km / 1-yr intervals); CarDekho page gives no figures. Same schedule for petrol and AMT.'],
  ['CNG extra upkeep','Spinny claims ≈₹43k extra over 5 yrs for CNG-system tests – a single source, which I treat as an upper bound. I use ₹12k (estimate) – ask your dealer for the CNG kit service price.'],
  ['Mileage (petrol MT)','ARAI 20.09; owners ≈18.5–19 kmpl (CarWale/Autocar user reports). Autocar’s own test returned 10.3 city / 16.1 highway (13.2 overall) – harsh test route.'],
  ['Mileage (AMT)','ARAI 18.8; Autocar tested 10.7 / 16.9 (13.8 overall); a learner owner reports ≈10 kmpl. I use 17.3 kmpl (MT owner figure scaled by the ARAI gap) – an estimate.'],
  ['Mileage (CNG)','ARAI 26.99 km/kg; Autocar tested the CNG AMT at 18.9 city / 25.4 highway; Spinny quotes 24–26. I use 23 km/kg (estimate).'],
  ['Turbo petrol','120 PS / 170 Nm 1.2 turbo (manual only). Autocar overall 13.2 kmpl tested; I use 16.5 kmpl (estimate – no owner data found).'],
  ['CNG trade-offs','Output drops 88 → 73 PS and 115 → 103 Nm on CNG; 210 L boot; Autocar team: “not the best choice for sustained highway use”.'],
  ['AMT','Owner reports of jerk in traffic; one petrol-AMT owner reported a flat battery twice in 2,200 km. Allowance ₹10k (estimate, no repair prices found).'],
  ['Insurance','Premium = IRDAI third-party (₹10,640 for 3 yrs, 1,000–1,500 cc, +18% GST) + own-damage on the IDV. Costlier variants (CNG, AMT, turbo) carry a higher OD premium purely through price; third-party is the same for all Punch engines.']],
 xuv3xo:[
  ['Service','Spinny 5-yr table ₹31,580 (yr 1 ₹3.96k … yr 4 ₹9.17k); this page does not split petrol/diesel. I add ₹4k for diesel (estimate) and ₹12k for CNG (estimate).'],
  ['Mileage (petrol MT)','ARAI 18.89; owners ≈17 kmpl (CarWale). Spinny: 1.2 TCMPFi city 12–14 / highway 15–17.'],
  ['Mileage (petrol AT)','ARAI 17.96; Spinny says the automatic is ≈1 kmpl below the manual in both city and highway. I use 16 kmpl.'],
  ['Mileage (TGDi 130 PS)','ARAI 20.1 (MT) / 18.2 (AT). Spinny: 12–15 city / 16–18 highway (MT), 11–13 / 15–17 (AT). I use 14.5 / 13.5 kmpl (estimate).'],
  ['Mileage (diesel)','ARAI 20.6 MT / 21.2 AMT. Autocar tested the diesel MT at 13.5 city / 17.4 highway. Spinny: 15–17 / 18–21. I use 19 kmpl for both (owner-based; the test figure was lower).'],
  ['Diesel AMT','Spinny: AMT matches the manual in city and is slightly better on the highway. Mahindra AMTs have a poor history (TUV300) but no 3XO-specific fault reports found. Allowance ₹10k (estimate).'],
  ['CNG','Launched at ₹9.99 L (MX Edge); 1.2 turbo-petrol, 111 PS / 200 Nm in both modes, manual only, claimed 24.7 km/kg, 270 L boot with twin tanks (Autocar India). No owner mileage yet, so the running cost uses ARAI × 67%/82%.'],
  ['Insurance','Spinny’s TCO assumes ₹15,072 a year third-party-style cost; my model uses IRDAI’s ₹10,640 for 3 yrs + GST, then own-damage on a falling IDV with NCB. XUV 3XO variants cost more, so own-damage is higher than Punch.']]
